import { isPlatformBrowser } from '@angular/common';
import { Component, inject, OnInit, PLATFORM_ID, signal } from '@angular/core';

@Component({
  selector: 'app-reading-progress',
  template: `<div class="bar" [style.width.%]="percent()"></div>`,
})
export class ReadingProgress implements OnInit {
  private readonly isBrowser = isPlatformBrowser(inject(PLATFORM_ID));
  // Missed one: field initializers run on the server too,
  // so this line throws "window is not defined" there
  private readonly height = window.innerHeight;
  readonly percent = signal(0);

  ngOnInit() {
    if (this.isBrowser) {
      // Added after the first crash; never removed on destroy
      window.addEventListener('scroll', () => this.percent.set(
        (scrollY / (document.body.scrollHeight - this.height)) * 100,
      ));
    }
  }
}

import {
  afterNextRender, Component, DestroyRef, inject, signal,
} from '@angular/core';

@Component({
  selector: 'app-reading-progress',
  template: `<div class="bar" [style.width.%]="percent()"></div>`,
})
export class ReadingProgress {
  // Rendered as 0 on the server and on the first browser render
  readonly percent = signal(0);
  constructor() {
    const destroyRef = inject(DestroyRef);
    // Browser only, after rendering: window and layout are safe here
    afterNextRender(() => {
      const onScroll = () => {
        const max = document.body.scrollHeight - window.innerHeight;
        this.percent.set(max > 0 ? (window.scrollY / max) * 100 : 0);
      };
      window.addEventListener('scroll', onScroll);
      destroyRef.onDestroy(() =>
        window.removeEventListener('scroll', onScroll));
    });
  }
}

