import { Injectable } from '@angular/core';

// Components inject the capability; each platform provides its own
export abstract class KeyValueStore {
  abstract get(key: string): string | null;
}

@Injectable()
export class BrowserStore implements KeyValueStore {
  get(key: string) { return localStorage.getItem(key); }
}

@Injectable()
export class ServerStore implements KeyValueStore {
  get(key: string) { return null; } // nothing saved to read during SSR
}
